export const findBenefitPlanById = (
  policies: Policys[],
  policyId?: string,
): Policys | undefined =>
  policies.find((policy: Policys): boolean => policy.id === policyId);

const policyEffectiveTime = (policy: Policys): number => {
  const effectiveTime = Date.parse(policy.effectiveDate);

  return Number.isFinite(effectiveTime) ? effectiveTime : Number.NEGATIVE_INFINITY;
};

export const selectPurchasedConsultPolicy = (
  policies: Policys[],
  planId: string,
): Policys | undefined =>
  policies
    .filter((policy: Policys): boolean => policy.plan.id === planId)
    .reduce<Policys | undefined>((latest: Policys | undefined, policy: Policys) => {
      if (!latest || policyEffectiveTime(policy) >= policyEffectiveTime(latest)) {
        return policy;
      }

      return latest;
    }, undefined);

export const shouldShowMatchedDoctor = (
  enteredFromJoinRoom: boolean,
  selectedPlanId: string | undefined,
  recommendedPlanId: string | undefined,
): boolean => {
  if (!enteredFromJoinRoom) {
    return true;
  }

  return Boolean(
    selectedPlanId &&
      recommendedPlanId &&
      selectedPlanId === recommendedPlanId,
  );
};

export const shouldReturnToConsultAfterEmptyDoctorToast = (

[$routeNames.productWaitingRoom]: {
  id: string;
  payUrl:string;
  resumeDoctorDetailPlanId?: string;
