import React, { useCallback, useState } from 'react';
import { ScrollView, TouchableOpacity } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';

import type { Policys } from '@api/api-types';
import AppText from '@components/app-text/app-text';
import { fetchSelectableBenefitPlans } from '@services/benefit-plan-service';
import { useAppState } from '@store/AppContext.tsx';

import styles from './consult-screen.styles';

const ConsultPlanChips = (): React.ReactElement | null => {
  const { plan, selectedPolicies, setPlan, setSelectedPolicies } = useAppState();
  const [policies, setPolicies] = useState<Policys[]>([]);
  const selectedPlanId = plan?.id;

  useFocusEffect(
    useCallback((): (() => void) => {
      let active = true;

      const loadPolicies = async (): Promise<void> => {
        try {
          const nextPolicies = await fetchSelectableBenefitPlans();

          if (active) {
            setPolicies(nextPolicies);
          }
        } catch (_error) {
          if (active) {
            setPolicies([]);
          }
        }
      };

      loadPolicies().then();

      return (): void => {
        active = false;
      };
    }, []),
  );

  const handleSelectPolicy = useCallback((policy: Policys): void => {
    if (
      policy.plan.id === selectedPlanId &&
      policy.id === selectedPolicies?.id
    ) {
      return;
    }

    setPlan(policy.plan);
    setSelectedPolicies(policy);
  }, [selectedPlanId, selectedPolicies?.id, setPlan, setSelectedPolicies]);

  if (policies.length === 0 || !selectedPlanId) {
    return null;
  }

  return (
    <ScrollView
      contentContainerStyle={styles.planChipContent}
      horizontal
      showsHorizontalScrollIndicator={false}
      style={styles.planChipScroll}
      testID="consult-plan-chips"
    >
      {policies.map((policy: Policys): React.ReactElement => {
        const selected = policy.plan.id === selectedPlanId;

        return (
          <TouchableOpacity
            accessibilityLabel={policy.plan.name}
            accessibilityRole="button"
            accessibilityState={{ selected }}
            activeOpacity={0.8}
            key={policy.id}
            onPress={(): void => handleSelectPolicy(policy)}
            style={[styles.planChip, selected ? styles.planChipSelected : null]}
            testID={`consult-plan-chip-${policy.id}`}
          >
            <AppText
              numberOfLines={1}
              style={[
                styles.planChipText,
                selected ? styles.planChipTextSelected : null,
              ]}
            >
              {policy.plan.name}
            </AppText>
          </TouchableOpacity>
        );
      })}
    </ScrollView>
  );
};

export default ConsultPlanChips;

