export const getProviderServiceIndex = (
  selectedService: string,
  services: readonly string[],
  allServicesOption: string,
): number => {
  if (selectedService === allServicesOption) {
    return -1;
  }

  return services
    .filter((service: string): boolean => service !== allServicesOption)
    .indexOf(selectedService);
};

export const remapProviderServiceSelection = (
  serviceIndex: number,
  nextProviderServices: readonly string[],
  allServicesOption: string,
): string => {
  if (serviceIndex < 0) {
    return allServicesOption;
  }

  const mappedService = nextProviderServices[serviceIndex];

  return mappedService && mappedService !== allServicesOption
    ? mappedService
    : allServicesOption;
};

import {
  getProviderServiceIndex,
  remapProviderServiceSelection,
} from '../src/screens/consult-screen/consult-service-selection';

const ALL_SERVICES = 'all_services';

describe('consult service selection across languages', () => {
  test('keeps All Services when no department is selected', () => {
    expect(
      getProviderServiceIndex(
        ALL_SERVICES,
        [ALL_SERVICES, '普通科', '外科'],
        ALL_SERVICES,
      ),
    ).toBe(-1);
    expect(
      remapProviderServiceSelection(
        -1,
        ['General Practitioner', 'Surgery'],
        ALL_SERVICES,
      ),
    ).toBe(ALL_SERVICES);
  });

  test('maps the selected department onto the same index in the new language', () => {
    const selectedIndex = getProviderServiceIndex(
      '普通科',
      [ALL_SERVICES, '普通科', '外科'],
      ALL_SERVICES,
    );

    expect(selectedIndex).toBe(0);
    expect(
      remapProviderServiceSelection(
        selectedIndex,
        ['General Practitioner', 'Surgery'],
        ALL_SERVICES,
      ),
    ).toBe('General Practitioner');
  });

  test('falls back to All Services when the new language has no department at that index', () => {
    expect(
      remapProviderServiceSelection(3, ['General Practitioner'], ALL_SERVICES),
    ).toBe(ALL_SERVICES);
  });
});

