useEffect((): (() => void) => {
  const planChanged =
    providerOptionsPlanKeyRef.current !== providerOptionsPlanKey;
  providerOptionsPlanKeyRef.current = providerOptionsPlanKey;
  const preservedServiceIndex = planChanged
    ? -1
    : selectedServiceIndexRef.current;

  countryRequestId.current += 1;
  const serviceRequestIdAtStart = serviceRequestId.current + 1;
  serviceRequestId.current = serviceRequestIdAtStart;
  setCountryOptionsQueryKey(undefined);
  setIsCountryPickerVisible(false);
  setIsServicePickerVisible(false);

  if (preservedServiceIndex < 0) {
    // A plan change gets a new specialty list, so the previous department
    // must not be sent with the next provider query. Language changes keep
    // the selected index and remap it after the localized options return.
    selectedServiceIndexRef.current = -1;
    serviceManuallySelectedRef.current = false;
    setIsRemappingService(false);
    setServices([]);
    setSelectedService(ALL_SERVICES_OPTION);
    setIsLoadingServices(false);

    return (): void => undefined;
  }

  setIsRemappingService(true);
  setIsLoadingServices(true);
  setServices([]);
  let isCurrent = true;

  const remapSelectedService = async (): Promise<void> => {
    try {
      const response = await requestProviderOptions();

      if (!isCurrent || serviceRequestId.current !== serviceRequestIdAtStart) {
        return;
      }

      const providerServices = getProviderSpecialties(response);
      const nextServices = hasProviderOptionPlanFilter
        ? providerServices
        : [
            ALL_SERVICES_OPTION,
            ...providerServices.filter(
              (specialty: string): boolean =>
                specialty !== ALL_SERVICES_OPTION,
            ),
          ];
      const mappedService = remapProviderServiceSelection(
        preservedServiceIndex,
        providerServices,
        ALL_SERVICES_OPTION,
      );
      const nextSelectedService = nextServices.includes(mappedService)
        ? mappedService
        : ALL_SERVICES_OPTION;

      selectedServiceIndexRef.current = getProviderServiceIndex(
        nextSelectedService,
        nextServices,
        ALL_SERVICES_OPTION,
      );
      serviceManuallySelectedRef.current =
        selectedServiceIndexRef.current >= 0;
      setServices(nextServices);
      setSelectedService(nextSelectedService);
    } catch (_error) {
      if (!isCurrent || serviceRequestId.current !== serviceRequestIdAtStart) {
        return;
      }

      selectedServiceIndexRef.current = -1;
      serviceManuallySelectedRef.current = false;
      setServices(
        hasProviderOptionPlanFilter ? [] : [ALL_SERVICES_OPTION],
      );
      setSelectedService(ALL_SERVICES_OPTION);
    } finally {
      if (isCurrent && serviceRequestId.current === serviceRequestIdAtStart) {
        setIsLoadingServices(false);
        setIsRemappingService(false);
      }
    }
  };

  remapSelectedService().then();

  return (): void => {
    isCurrent = false;
  };
}, [
  hasProviderOptionPlanFilter,
  providerOptionsPlanKey,
  providerOptionsQueryKey,
  requestProviderOptions,
]);

