const SPECIALTY_ALIAS_GROUPS: readonly (readonly string[])[] = [
  ['普通科', 'General Practitioner'],
  ['外科', 'General Surgery'],
  ['肠胃肝脏科', '腸胃肝臟科', 'Gastroenterology & Hepatology'],
