  ['临床微生物及感染学', '臨床微生物及感染學', 'Clinical Microbiology & Infection'],
  ['危重病学', '危重病學', 'Intensive Care'],
  ['物理治疗', '物理治療', 'Physiotherapy'],
  ['社会医学', '社會醫學', 'Community Medicine'],
  ['心胸肺外科', '心胸肺外科', 'Cardio-thoracic Surgery'],
  ['急症科', '急症科', 'Emergency Medicine'],
  ['儿科', '兒科', 'Paediatrics'],
  ['Dermatology'],
];

const normalizeSpecialtyName = (specialty: string): string =>
  specialty.trim().toLowerCase();

const findSpecialtyAliasGroup = (
  specialty: string,
): readonly string[] | undefined => {
  const normalizedSpecialty = normalizeSpecialtyName(specialty);

  return SPECIALTY_ALIAS_GROUPS.find((group: readonly string[]): boolean =>
    group.some(
      (alias: string): boolean =>
        normalizeSpecialtyName(alias) === normalizedSpecialty,
    ),
  );
};

export const getProviderServiceIndex = (
  selectedService: string,
  services: readonly string[],
  allServicesOption: string,
): number => {
  if (selectedService === allServicesOption) {
    return -1;
  }

  return services
    .filter((service: string): boolean => service !== allServicesOption)
    .indexOf(selectedService);
};

export const remapSelectedService = (
  selectedService: string,
  selectedIndex: number,
  nextProviderServices: readonly string[],
  allServicesOption: string,
): string => {
  if (
    selectedService === allServicesOption ||
    selectedService.trim().length === 0
  ) {
    return allServicesOption;
  }

  const exactMatch = nextProviderServices.find(
    (service: string): boolean =>
      normalizeSpecialtyName(service) === normalizeSpecialtyName(selectedService),
  );

  if (exactMatch) {
    return exactMatch;
  }

  const aliasGroup = findSpecialtyAliasGroup(selectedService);
  const aliasMatch = aliasGroup
    ? nextProviderServices.find((service: string): boolean =>
        aliasGroup.some(
          (alias: string): boolean =>
            normalizeSpecialtyName(alias) === normalizeSpecialtyName(service),
        ),
      )
    : undefined;

  if (aliasMatch) {
    return aliasMatch;
  }

  const indexedService =
    selectedIndex >= 0 ? nextProviderServices[selectedIndex] : undefined;

  return indexedService && indexedService !== allServicesOption
    ? indexedService
    : allServicesOption;
};

import {
  getProviderServiceIndex,
  remapSelectedService,
} from '../src/screens/consult-screen/consult-service-selection';

