  ws.send(JSON.stringify({ id, method, params }));
  return id;
};

const argText = (arg) => {
  if (!arg) return '';
  if (Object.prototype.hasOwnProperty.call(arg, 'value')) {
    return typeof arg.value === 'string' ? arg.value : JSON.stringify(arg.value);
  }
  if (arg.unserializableValue) return String(arg.unserializableValue);
  if (arg.preview && Array.isArray(arg.preview.properties)) {
    const props = arg.preview.properties
      .map((prop) => `${prop.name}:${prop.value ?? prop.type}`)
      .join(',');
    return `${arg.preview.description || arg.className || 'Object'}{${props}}`;
  }
  return arg.description || arg.type || '';
};

const interesting = (line) =>
  /api-client\.ts|ConsultDoctorList|fetchDoctors|Exception encountered|handleRequestError|filterBySpecialty|ticketList|selectablePlans/.test(line);

