export type DoctorBookingDestination = 'questionnaire' | 'appointment';

export type DoctorConfirmAction = 'book' | 'purchase-plan' | 'choose-plan';

export const getDoctorBookingDestination = (
  skipQuestionnaire?: boolean
): DoctorBookingDestination =>
  skipQuestionnaire === true ? 'appointment' : 'questionnaire';

export const resolveDoctorConfirmAction = (
  purchasedPolicyIds: readonly string[],
  selectedPolicyId: string | undefined,
): DoctorConfirmAction => {
  if (purchasedPolicyIds.length === 0) {
    return 'purchase-plan';
  }

  if (
    typeof selectedPolicyId === 'string' &&
    selectedPolicyId.length > 0 &&
    purchasedPolicyIds.includes(selectedPolicyId)
  ) {
    return 'book';
  }

  return 'choose-plan';
};

