const handleContinueBooking = async (): Promise<void> => {
  setLoading(true);

  let bookingPayorId = "";
  let bookingPolicyId = "";

  try {
    const purchasedPlans = await fetchSelectableBenefitPlans();
    const confirmAction = resolveDoctorConfirmAction(
      purchasedPlans.map((policy) => policy.id),
      selectedPolicies?.id,
    );

    if (confirmAction === "purchase-plan") {
      const [optionsResponse, productListResponse] = await Promise.all([
        $api.getProviderOptions(),
        $api.heals_pass_product_list(),
      ]);
      const nextPassProduct = selectConsultPassProduct(
        optionsResponse,
        productListResponse,
      );

      setLoading(false);

      if (!nextPassProduct) {
        setCommonModalKey("showErrorModal");
        setErrorModalText($i18n.t("unknown_error"));
        setShowErrorModal(true);
        return;
      }

      setConsultPassProduct(nextPassProduct);
      setIsNoPassModalVisible(true);
      return;
    }

    if (confirmAction === "choose-plan") {
      setLoading(false);
      setCommonModalKey("showErrorModal");
      setErrorModalText($i18n.t("please_choose_plan"));
      setShowErrorModal(true);
      return;
    }

    const selectedPurchasedPlan = purchasedPlans.find(
      (policy) => policy.id === selectedPolicies?.id,
    );

    bookingPayorId = selectedPurchasedPlan?.plan.payorId ?? "";
    bookingPolicyId = selectedPurchasedPlan?.id ?? "";
  } catch (error) {
    console.log(
      "Exception encountered @ DoctorDetailScreen.checkPurchasedPlan",
      error,
    );
    setLoading(false);
    return;
  }

  setLoading(true);

